/** A slot of an inventory (C1b decision for I §8.2's transfers: the sim has no notion of an open window, so an action names the inventory). owner tag 0 is the acting player's own inventory */
export interface InvSlot {
  owner: EntityRef;
  inv: number;
  slot: number;
}
export const InvSlotCodec = {
  /** The encoded size in bytes. */
  SIZE: 12,
  /** Byte offsets of the fields. */
  OFFSET: { owner: 0, inv: 8, slot: 10 },
  /** A value with every field at its default. */
  defaults(): InvSlot {
    return { owner: EntityRefCodec.defaults(), inv: 1, slot: 0 };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    inv: (v: DataView, o: number): number => v.getUint8(o + 8),
    slot: (v: DataView, o: number): number => v.getUint16(o + 10, true),
  },
  read(r: Reader, _field?: string): InvSlot {
    
    const f_owner = EntityRefCodec.read(r, "InvSlot.owner");
    const f_inv = InventoryTypeCodec.read(r, "InvSlot.inv");
    r.zeros(1, "InvSlot.reserved");
    const f_slot = r.u16("InvSlot.slot");
    const v: InvSlot = { owner: f_owner, inv: f_inv, slot: f_slot };
    
    return v;
  },
  write(w: Writer, v: InvSlot, _field?: string): void {
    
    EntityRefCodec.write(w, v.owner, "InvSlot.owner");
    InventoryTypeCodec.write(w, v.inv, "InvSlot.inv");
    w.zeros(1);
    w.u16(v.slot, "InvSlot.slot");
  },
  /** The value's 12 bytes. */
  encode(v: InvSlot): Uint8Array {
    const w = new Writer();
    InvSlotCodec.write(w, v);
    return w.finish();
  },
  /** Decodes a value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): InvSlot {
    const r = new Reader(bytes);
    const v = InvSlotCodec.read(r, "InvSlot");
    r.finish("InvSlot");
    return v;
  },
  compare(a: InvSlot, b: InvSlot): number {
    { const c = EntityRefCodec.compare(a.owner, b.owner); if (c !== 0) return c; }
    { const c = cmpScalar(a.inv, b.inv); if (c !== 0) return c; }
    { const c = cmpScalar(a.slot, b.slot); if (c !== 0) return c; }
    return 0;
  },
  dump(d: Dump, v: InvSlot, prefix = ''): void {
    EntityRefCodec.dump(d, v.owner, `${`${prefix}owner`}.`);
    d.int(`${prefix}inv`, v.inv);
    d.int(`${prefix}slot`, v.slot);
  },
};

