/** One slot of the slot heap (§4.5); count 0 means empty, and an empty slot's key is ItemKey none */
export interface Slot {
  key: number;
  count: number;
}
export const SlotCodec = {
  /** The encoded size in bytes. */
  SIZE: 6,
  /** Byte offsets of the fields. */
  OFFSET: { key: 0, count: 2 },
  /** A value with every field at its default. */
  defaults(): Slot {
    return { key: 0, count: 0 };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    key: (v: DataView, o: number): number => v.getUint16(o + 0, true),
    count: (v: DataView, o: number): number => v.getInt32(o + 2, true),
  },
  read(r: Reader, _field?: string): Slot {
    
    const f_key = ItemKeyCodec.read(r, "Slot.key");
    const f_count = r.i32("Slot.count");
    const v: Slot = { key: f_key, count: f_count };
    
    return v;
  },
  write(w: Writer, v: Slot, _field?: string): void {
    
    ItemKeyCodec.write(w, v.key, "Slot.key");
    w.i32(v.count, "Slot.count");
  },
  /** The value's 6 bytes. */
  encode(v: Slot): Uint8Array {
    const w = new Writer();
    SlotCodec.write(w, v);
    return w.finish();
  },
  /** Decodes a value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): Slot {
    const r = new Reader(bytes);
    const v = SlotCodec.read(r, "Slot");
    r.finish("Slot");
    return v;
  },
  compare(a: Slot, b: Slot): number {
    { const c = cmpScalar(a.key, b.key); if (c !== 0) return c; }
    { const c = cmpScalar(a.count, b.count); if (c !== 0) return c; }
    return 0;
  },
  dump(d: Dump, v: Slot, prefix = ''): void {
    d.int(`${prefix}key`, v.key);
    d.int(`${prefix}count`, v.count);
  },
};

