/** A building centre in doubled tile units (§4.2) */
export interface TilePos2 {
  x2: number;
  y2: number;
}
export const TilePos2Codec = {
  /** The encoded size in bytes. */
  SIZE: 8,
  /** Byte offsets of the fields. */
  OFFSET: { x2: 0, y2: 4 },
  /** A value with every field at its default. */
  defaults(): TilePos2 {
    return { x2: 0, y2: 0 };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    x2: (v: DataView, o: number): number => v.getInt32(o + 0, true),
    y2: (v: DataView, o: number): number => v.getInt32(o + 4, true),
  },
  read(r: Reader, _field?: string): TilePos2 {
    
    const f_x2 = r.i32("TilePos2.x2");
    const f_y2 = r.i32("TilePos2.y2");
    const v: TilePos2 = { x2: f_x2, y2: f_y2 };
    
    return v;
  },
  write(w: Writer, v: TilePos2, _field?: string): void {
    
    w.i32(v.x2, "TilePos2.x2");
    w.i32(v.y2, "TilePos2.y2");
  },
  /** The value's 8 bytes. */
  encode(v: TilePos2): Uint8Array {
    const w = new Writer();
    TilePos2Codec.write(w, v);
    return w.finish();
  },
  /** Decodes a value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): TilePos2 {
    const r = new Reader(bytes);
    const v = TilePos2Codec.read(r, "TilePos2");
    r.finish("TilePos2");
    return v;
  },
  compare(a: TilePos2, b: TilePos2): number {
    { const c = cmpScalar(a.x2, b.x2); if (c !== 0) return c; }
    { const c = cmpScalar(a.y2, b.y2); if (c !== 0) return c; }
    return 0;
  },
  dump(d: Dump, v: TilePos2, prefix = ''): void {
    d.int(`${prefix}x2`, v.x2);
    d.int(`${prefix}y2`, v.y2);
  },
};

